class TopologyAwareGangScheduler:
    def __init__(self, rack_topology):
        self.topology = rack_topology # Node -> Switch -> Spine

    # Gang scheduling: all N GPUs must be allocated contiguously within the same InfiniBand rail
    def schedule_job(self, job_gpu_count: int):
        # BUG: Naive greedy allocation splits job across non-uniform fat-tree network paths
        selected_nodes = self.greedy_alloc(job_gpu_count)
        return selected_nodes
